package com.campus.trade.ai.dispute; import org.springframework.context.annotation.*; import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor; import java.util.concurrent.*; @Configuration public class DisputeAgentAsyncConfig { @Bean("disputeAiAssistExecutor") public Executor executor(){var e=new ThreadPoolTaskExecutor();e.setCorePoolSize(2);e.setMaxPoolSize(4);e.setQueueCapacity(50);e.setThreadNamePrefix("dispute-ai-assist-");e.setRejectedExecutionHandler(new ThreadPoolExecutor.CallerRunsPolicy());e.initialize();return e;} }
